import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    idx = 0
    n = int(data[idx]); idx += 1
    l = int(data[idx]); idx += 1
    r = int(data[idx]); idx += 1

    a = list(map(int, data[idx:idx+n])); idx += n
    b = list(map(int, data[idx:idx+n])); idx += n

    # Check positions outside [l, r]
    for i in range(n):
        if i < l - 1 or i > r - 1:
            if a[i] != b[i]:
                print("LIE")
                return

    # Check if multisets of the range [l, r] are the same
    from collections import Counter

    a_sub = a[l-1:r]
    b_sub = b[l-1:r]

    if Counter(a_sub) == Counter(b_sub):
        print("TRUTH")
    else:
        print("LIE")

if __name__ == "__main__":
    solve()
"}

