import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))
    l = int(next(it))
    r = int(next(it))

    # Convert to 0-indexed
    l -= 1
    r -= 1

    a = [int(next(it)) for _ in range(n)]
    b = [int(next(it)) for _ in range(n)]

    # Check elements outside the range [l, r]
    for i in range(n):
        if i < l or i > r:
            if a[i] != b[i]:
                print("LIE")
                return

    # Check if multisets inside [l, r] match
    # We can do this by comparing sorted lists
    if sorted(a[l:r+1]) == sorted(b[l:r+1]):
        print("TRUTH")
    else:
        print("LIE")

if __name__ == "__main__":
    solve()
"}

