def is_winning_position(x, y, vectors, d, anton_reflected, dasha_reflected, memo):
    if (x, y, anton_reflected, dasha_reflected) in memo:
        return memo[(x, y, anton_reflected, dasha_reflected)]

    # Check if current position is losing (distance > d)
    if x*x + y*y > d*d:
        return False  # Current player loses

    # Try all possible moves
    for (dx, dy) in vectors:
        nx, ny = x + dx, y + dy
        if nx*nx + ny*ny <= d*d:
            # Check if this move leads to a losing position for opponent
            if not is_winning_position(nx, ny, vectors, d, anton_reflected, dasha_reflected, memo):
                memo[(x, y, anton_reflected, dasha_reflected)] = True
                return True

    # Try reflection if available
    if not anton_reflected:
        nx, ny = y, x
        if nx*nx + ny*ny <= d*d:
            if not is_winning_position(nx, ny, vectors, d, True, dasha_reflected, memo):
                memo[(x, y, anton_reflected, dasha_reflected)] = True
                return True
    elif not dasha_reflected:
        nx, ny = y, x
        if nx*nx + ny*ny <= d*d:
            if not is_winning_position(nx, ny, vectors, d, anton_reflected, True, memo):
                memo[(x, y, anton_reflected, dasha_reflected)] = True
                return True

    # No winning moves
    memo[(x, y, anton_reflected, dasha_reflected)] = False
    return False

def solve():
    x, y, n, d = map(int, input().split())
    vectors = []
    for _ in range(n):
        dx, dy = map(int, input().split())
        vectors.append((dx, dy))

    # Initialize memoization
    memo = {}

    # Anton starts, both haven't reflected yet
    if is_winning_position(x, y, vectors, d, False, False, memo):
        print("Anton")
    else:
        print("Dasha")

solve()
