for _ in range(q):
    n, k = map(int, input().split())
    s = input().strip()

    # Get the valid patterns for length k
    patterns = []
    for i in range(3):
        pattern = ""
        for j in range(k):
            pattern += chr(ord('R') + (i + j) % 3)
        patterns.append(pattern)

    min_changes = k  # Maximum possible changes

    # Check all possible starting positions
    for start in range(n - k + 1):
        substring = s[start:start+k]

        # Check each pattern
        for pattern in patterns:
            changes = 0
            for ch1, ch2 in zip(substring, pattern):
                if ch1 != ch2:
                    changes += 1

            if changes < min_changes:
                min_changes = changes

    print(min_changes)
