t = int(sys.stdin.readline())
for _ in range(t):
    n, m = map(int, sys.stdin.readline().split())
    strings = [sys.stdin.readline().strip() for _ in range(n)]

    # Generate candidates within Hamming distance 1 of the first string
    base = strings[0]
    candidates = [base]

    for i in range(m):
        for ch in "abcdefghijklmnopqrstuvwxyz":
            if ch == base[i]:
                continue
            new_str = base[:i] + ch + base[i+1:]
            candidates.append(new_str)

    # Check each candidate
    found = False
    for cand in candidates:
        valid = True
        for s in strings:
            diff = 0
            for a, c in zip(s, cand):
                if a != c:
                    diff += 1
                    if diff > 1:
                        break
            if diff > 1:
                valid = False
                break
        if valid:
            print(cand)
            found = True
            break

    if not found:
        print(-1)
