def solve():
    n = int(input())
    a = list(map(int, input().split()))
    a.sort()

    parent = list(range(n))

    def find(u):
        while parent[u] != u:
            parent[u] = parent[parent[u]]
            u = parent[u]
        return u

    def union(u, v):
        pu, pv = find(u), find(v)
        if pu == pv:
            return False  # already connected
        parent[pu] = pv
        return True

    removals = 0

    # Connect elements in a way that avoids cycles
    for i in range(1, n):
        # Try to connect a[i] to its closest neighbor (either i-1 or i+1)
        # But we only connect if it doesn't create a cycle
        if union(i-1, i):
            continue
        else:
            removals += 1

    print(removals)

solve()
