from itertools import permutations

def find_super_lucky(n_str):
    n = int(n_str)

    # Try all even lengths starting from the length of n
    for length in range(len(n_str), 10000, 2):
        k = length // 2
        digits = ['4'] * k + ['7'] * k

        # Handle empty case (should never happen for valid n ≥ 1)
        if not digits:
            return '47'  # Minimum super lucky number

        # Generate all unique permutations
        unique_perms = set(permutations(digits))

        # Convert to integers and check
        valid_numbers = []
        for perm in unique_perms:
            num_str = ''.join(perm)
            if num_str:
                num = int(num_str)
            else:
                num = -1  # Should never happen

            if num >= n:
                valid_numbers.append(num_str)

        if valid_numbers:
            # Return the minimum one (lexicographically smallest)
            return min(valid_numbers)

    return None  # Should never reach here for valid input

n = input().strip()
result = find_super_lucky(n)
print(result)
