    # Try to split into two groups of n elements with equal sums
    # We'll use a different greedy approach: pick smallest elements first
    # And also try a few variations

    def try_split(group_size, target_sum, array):
        # Pick smallest elements first
        array_sorted = sorted(array)
        current_sum = 0
        current_group = []

        for num in array_sorted:
            if current_sum + num <= target_sum and len(current_group) < group_size:
                current_group.append(num)
                current_sum += num

        if len(current_group) == group_size and current_sum == target_sum:
            return current_group + array_sorted

        # Try picking largest elements first
        current_sum = 0
        current_group = []
        array_sorted = sorted(array)
        for i in range(len(array_sorted) - 1, -1, -1):
            num = array_sorted[i]
            if current_sum + num <= target_sum and len(current_group) < group_size:
                current_group.append(num)
                current_sum += num

        if len(current_group) == group_size and current_sum == target_sum:
            return current_group + array_sorted

        # Try a few more combinations
        # Pick one large, then small, then large, etc.
        current_sum = 0
        current_group = []
        array_sorted = sorted(array)

        # Pick largest first
        for i in range(len(array_sorted) - 1, -1, -1):
            if current_sum + array_sorted[i] <= target_sum and len(current_group) < group_size:
                current_group.append(array_sorted[i])
                current_sum += array_sorted[i]

        if len(current_group) == group_size and current_sum == target_sum:
            return current_group + array_sorted

        # Pick smallest first
        for num in array_sorted:
            if current_sum + num <= target_sum and len(current_group) < group_size:
                current_group.append(num)
                current_sum += num

        if len(current_group) == group_size and current_sum == target_sum:
            return current_group + array_sorted

        return None

    result = try_split(n, total_sum // 2, a)

