    # - Else (all elements distinct), we need to check if we can split
    if len(set(a)) < 2n:
        # There's at least one duplicate, we can split
        # Output a split where each half has n elements

        # Try to build the first half by picking smallest elements first
        a_sorted = sorted(a)
