        second_half = a_sorted[n:]

        print(' '.join(map(str, first_half + second_half)))
    else:
        # All elements distinct, check if we can split into two equal halves
        # We need to find n elements that sum to total_sum // 2

        # Use a greedy approach with backtracking
        a_sorted = sorted(a)

