n, m = map(int, input().split())
table = [input().strip() for _ in range(n)]

def is_good(table):
    """Check if table is good: rows are ordered lexicographically"""
    for i in range(n - 1):
        if table[i] > table[i + 1]:
            return False
    return True

# Try removing columns one by one until we get a good table
remaining_columns = set(range(m))
removed_columns = 0

# Try removing each column to see if it helps
for col in range(m):
    # Temporarily remove this column and check
    temp_remaining = remaining_columns - {col}
    temp_table = [[row[j] for j in temp_remaining] for row in table]
    if is_good(temp_table):
        remaining_columns.remove(col)
        removed_columns += 1
        break

# If it's still not good, we need to remove more columns
while not is_good([[row[j] for j in remaining_columns] for row in table]):
    # Find the column that, when removed, will make it good
    for col in list(remaining_columns):
        temp_remaining = remaining_columns - {col}
        temp_table = [[row[j] for j in temp_remaining] for row in table]
        if is_good(temp_table):
            remaining_columns.remove(col)
            removed_columns += 1
            break

print(removed_columns)
