import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    a = list(map(int, data[1:n+1]))
    s = data[n+1]

    # Convert binary string s to integer m
    m = int(s, 2)

    # For each possible x from 0 to m, calculate f(x) and find maximum
    max_val = 0
    for x in range(m + 1):
        val = 0
        for i in range(n):
            if x & (1 << i):
                val += a[i]
        max_val = max(max_val, val)

    print(max_val)

if __name__ == "__main__":
    solve()
