    for _ in range(t):
        n, m = map(int, input().split())
        strings = [input().strip() for _ in range(n)]

        # For each position, we'll try each possible character
        # We'll use backtracking to find a valid solution

        # Helper function to check if a partial solution is valid
        def is_valid(solution):
            diffs = [0] * n
            for i in range(n):
                for j in range(m):
                    if solution[j] != strings[i][j]:
                        diffs[i] += 1
                        if diffs[i] > 1:
                            return False
            return True

        # Try all possible combinations using backtracking
        result = None

        def backtrack(pos, solution):
            nonlocal result
            if pos == m:
                result = ''.join(solution)
                return True

            # Try each possible character for this position
            for c in 'abcdefghijklmnopqrstuvwxyz':
                solution[pos] = c
                if is_valid(solution):
                    if backtrack(pos + 1, solution):
                        return True
                solution[pos] = ''
            return False

        solution = [''] * m
        if backtrack(0, solution):
            print(result)
        else:
            print(-1)

