n, m = map(int, input().split())

# Build adjacency list
adj = [[] for _ in range(n + 1)]
for _ in range(m):
    u, v = map(int, input().split())
    adj[u].append(v)
    adj[v].append(u)

# Bipartition check using BFS
from collections import deque

color = [-1] * (n + 1)

# Check if bipartite and find color classes
is_bipartite = True
for start in range(1, n + 1):
    if color[start] == -1:
        queue = deque([start])
        color[start] = 0
        while queue:
            u = queue.popleft()
            for v in adj[u]:
                if color[v] == -1:
                    color[v] = color[u] ^ 1
                    queue.append(v)
                elif color[v] == color[u]:
                    is_bipartite = False
                    break
            if not is_bipartite:
                break
        if not is_bipartite:
            break

if not is_bipartite:
    print(-1)
else:
    # Find color classes
    set0 = [i for i in range(1, n + 1) if color[i] == 0]
    set1 = [i for i in range(1, n + 1) if color[i] == 1]

    # Ensure neither set is empty
    if len(set0) == 0 or len(set1) == 0:
        print(-1)
    else:
        print(len(set0))
        print(' '.join(map(str, set0)))
        print(len(set1))
        print(' '.join(map(str, set1)))
