def solve():
    x, y, n, d = map(int, input().split())
    vectors = [tuple(map(int, input().split())) for _ in range(n)]

    # Memoization cache
    memo = {}

    def can_win(x, y, a_reflect, d_reflect, turn):
        # Check if we've already computed this state
        key = (x, y, a_reflect, d_reflect, turn)
        if key in memo:
            return memo[key]

        # Check if distance exceeds d
        dist = x*x + y*y
        if dist > d*d:
            # Current player loses
            memo[key] = False
            return False

        # Check if current player has winning moves
        for i in range(n):
            nx, ny = x + vectors[i][0], y + vectors[i][1]
            if not can_win(nx, ny, a_reflect, d_reflect, 1 - turn):
                memo[key] = True
                return True

        # Check if reflection is available
        if turn == 0 and not a_reflect:
            # Anton's turn and he hasn't reflected yet
            nx, ny = y, x  # Reflect across y=x
            if not can_win(nx, ny, True, d_reflect, 1 - turn):
                memo[key] = True
                return True
        elif turn == 1 and not d_reflect:
            # Dasha's turn and she hasn't reflected yet
            nx, ny = y, x  # Reflect across y=x
            if not can_win(nx, ny, a_reflect, True, 1 - turn):
                memo[key] = True
                return True

        # No winning moves
        memo[key] = False
        return False

    if can_win(x, y, False, False, 0):
        print("Anton")
    else:
        print("Dasha")

solve()
