import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    H = int(data[0])
    n = int(data[1])
    d = list(map(int, data[2:2+n]))

    # Calculate prefix sums
    prefix = [0] * (n + 1)
    for i in range(1, n + 1):
        prefix[i] = prefix[i-1] + d[i-1]

    total = prefix[n]

    if total >= 0:
        print(-1)
        return

    min_result = -1

    # Try each minute in the next round
    for m in range(1, n + 1):
        # We need H + k * total + prefix[m] <= 0
        # => k * total <= -H - prefix[m]
        # => k >= ceil((-H - prefix[m]) / total)
        needed = -H - prefix[m]

        if total > 0:
            k = (needed + total - 1) // total
        else:
            k = (needed + total + 1) // total

        if k >= 0:
            result = k * n + m
            if result < min_result or min_result == -1:
                min_result = result

    print(min_result if min_result != -1 else -1)

if __name__ == "__main__":
    solve()
"}

