        left_to_peak[peak] = m[peak]

        # Build non-increasing from peak to right
        right_from_peak = [0] * n
        right_from_peak[peak] = m[peak]
        for i in range(peak+1, n):
            right_from_peak[i] = min(m[i], right_from_peak[i-1] + 1)

        # Combine
        result = [0] * n
        for i in range(n):
            if i <= peak:
                result[i] = left_to_peak[i]
            else:
                result[i] = right_from_peak[i]

        # Check if result is valid
        valid = True
        for i in range(n):
            # Check if there's a j < i < k with a[j] > a[i] < a[k]
