def solve():
    n, m, w = map(int, input().split())
    weights = list(map(int, input().split()))
    beauties = list(map(int, input().split()))

    # Find friendship groups using Union-Find
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(x, y):
        px, py = find(x), find(y)
        if px != py:
            parent[py] = px

    for _ in range(m):
        x, y = map(int, input().split())
        union(x - 1, y - 1)  # Convert to 0-index

    # Group Hoses by their root
    from collections import defaultdict
    groups = defaultdict(list)
    for i in range(n):
        root = find(i)
        groups[root].append(i)

    # For each group, calculate total weight and beauty
    # Also find the Hose with max beauty/weight ratio
    dp = [0] * (w + 1)

    for group in groups.values():
        total_weight = sum(weights[i] for i in group)
        total_beauty = sum(beauties[i] for i in group)

        # Find the Hose with max beauty/weight ratio
        max_ratio_beauty = 0
        max_ratio_index = -1
        max_ratio_weight = w + 1

        for i in group:
            if weights[i] <= max_ratio_weight:
                ratio = beauties[i] / weights[i]
                if ratio > max_ratio_beauty:
                    max_ratio_beauty = ratio
                    max_ratio_index = i
                    max_ratio_weight = weights[i]

        # Option 1: take the whole group
        if total_weight <= w:
            for cap in range(w, total_weight - 1, -1):
                dp[cap] = max(dp[cap], dp[cap - total_weight] + total_beauty)

        # Option 2: take one Hose from the group
        if max_ratio_weight <= w:
            for cap in range(w, max_ratio_weight - 1, -1):
                dp[cap] = max(dp[cap], dp[cap - max_ratio_weight] + beauties[max_ratio_index])

    print(dp[w])

