def find_vertices(contamination, N):
    """Find the vertices of the polygon"""
    vertices = []

    # For each cell, check if any of its corners are vertices
    for cell_x in range(N):
        for cell_y in range(N):
            # Check all 4 corners of the cell
            for dx, dy in [(0, 0), (1, 0), (0, 1), (1, 1)]:
                x = cell_x + dx
                y = cell_y + dy

                # Check if this point is a vertex
                if 2 <= x <= N-2 and 2 <= y <= N-2:
                    # Check neighboring cells to see if this is a sharp corner
                    # If the contamination level changes significantly, it's a vertex
                    sum_level = 0
                    for cx, cy in [(0, 0), (1, 0), (0, 1), (1, 1)]:
                        nx = cell_x + cx - dx
                        ny = cell_y + cy - dy

                        if 0 <= nx < N and 0 <= ny < N:
                            sum_level += int(contamination[ny][nx])

                    # If the sum of levels around this point is large, it's a vertex
                    if sum_level >= 20:
                        vertices.append((x, y))

    return vertices


def solve(contamination, N):
    """Recover the polygon vertices"""
    vertices = find_vertices(contamination, N)

    # Sort vertices clockwise
    vertices.sort(key=lambda p: (p[1], p[0]))  # Sort by y, then x

    # Use the cross product to determine clockwise order
    def cross(o, a, b):
        return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

    # Find the lexicographically smallest vertex
    start = min(vertices)

    # Sort vertices in clockwise order
    vertices.sort(key=lambda p: (-cross(start, start, p)))

