def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    it = iter(data)
    n = int(next(it))

    # Read costs
    c1 = [int(next(it)) for _ in range(n)]
    c2 = [int(next(it)) for _ in range(n)]
    c3 = [int(next(it)) for _ in range(n)]

    # Read edges
    edges = [[] for _ in range(n)]
    for _ in range(n - 1):
        u = int(next(it)) - 1
        v = int(next(it)) - 1
        edges[u].append(v)
        edges[v].append(u)

    # Build tree and root at 0
    parent = [-1] * n
    visited = [False] * n
    from collections import deque
    queue = deque([0])
    visited[0] = True

    while queue:
        v = queue.popleft()
        for u in edges[v]:
            if not visited[u]:
                visited[u] = True
                parent[u] = v
                queue.append(u)

    # Compute DP
    dp = [[0] * 3 for _ in range(n)]

    def dfs(v):
        for child in edges[v]:
            if child != parent[v]:
                dfs(child)

        # For each color of this vertex, compute cost
        for color in range(3):
            cost = (c1[v] if color == 0 else c2[v] if color == 1 else c3[v])
            for child in edges[v]:
                if child != parent[v]:
                    # Find minimum dp of child with color different from current color
                    min_dp = float('inf')
                    for child_color in range(3):
                        if child_color != color:
                            if dp[child][child_color] < min_dp:
                                min_dp = dp[child][child_color]
                    cost += min_dp
            dp[v][color] = cost

    dfs(0)

    answer = min(dp[0])

    # Reconstruct path
    color = dp[0].index(answer)
    result = [0] * n
    result[0] = color + 1

    def backtrack(v, chosen_color):
        for child in edges[v]:
            if child != parent[v]:
                # Find a child with a color different from chosen_color that gives the minimum total
                min_total = float('inf')
                best_child_color = -1
                for child_color in range(3):
                    if child_color != chosen_color:
                        if dp[child][child_color] < min_total:
                            min_total = dp[child][child_color]
