def can_transform(a: str, b: str) -> bool:
    """Check if we can transform a into b using the allowed operations."""
    n = len(a)
    diff = [0] * n

    # Calculate difference array: diff[i] = 0 if a[i] == b[i], else 1
    for i in range(n):
        diff[i] = 1 if a[i] != b[i] else 0

    # We'll track the number of 0s and 1s in the current prefix
