def solve():
    n = int(input())
    cards = input().split()

    if n == 1:
        print(0)
        return

    # Count occurrences of each card type
    card_count = {}
    for card in cards:
        card_count[card] = card_count.get(card, 0) + 1

    # Check if all cards are the same type
    if len(card_count) == 1:
        print(0)
        return

    # Greedy approach to find minimum number of hints
    # We need to give hints until all cards are uniquely identifiable

    # We'll track for each card which hints it was part of
    # Start with no hints
    hints = set()

    # Function to check if all cards are uniquely identifiable
    def are_unique():
        # Create a mapping from card type to the set of hints it participates in
        signature = {}
        for card in cards:
            sig = set()
            for h in hints:
                if card in h:
                    sig.add(h)
            signature[card] = frozenset(sig)

        # Check if all signatures are unique
        return len(signature.values()) == len(signature)

    # Greedy algorithm
    while True:
        # If already unique, break
        if are_unique():
            break

        # Try all possible hints
        best_hint = None
        max_reduction = 0

        # Try color hints
        for color in set(c[0] for c in cards):
            # Create a set of cards of this color
            color_cards = {c for c in cards if c[0] == color}

            # Try adding this hint
            temp_hints = hints.copy()
            temp_hints.add(f"color::{color}")

            # Count how many pairs would become unique
            original_uniq = are_unique()

            # Count ambiguous pairs
            ambiguous = []
            for i in range(len(cards)):
                for j in range(i + 1, len(cards)):
                    if cards[i] != cards[j] and signature[cards[i]] == signature[cards[j]]:
                        ambiguous.append((i, j))

            # Count how many ambiguous pairs become unique
            temp_signature = {}
            for card in cards:
                sig = set()
                for h in temp_hints:
                    if card in h:
                        sig.add(h)
                temp_signature[card] = frozenset(sig)

            unique_pairs = 0
            for i, j in ambiguous:
                if temp_signature[cards[i]] != temp_signature[cards[j]]:
                    unique_pairs += 1

            reduction = len(ambiguous) - unique_pairs

            if reduction > max_reduction:
                max_reduction = reduction
                best_hint = f"color::{color}"

        # Try value hints
        for value in set(c[1] for c in cards):
            # Create a set of cards of this value
            value_cards = {c for c in cards if c[1] == value}

            # Try adding this hint
            temp_hints = hints.copy()
            temp_hints.add(f"value::{value}")

            # Count how many pairs would become unique
            original_uniq = are_unique()

            # Count ambiguous pairs
            ambiguous = []
            for i in range(len(cards)):
                for j in range(i + 1, len(cards)):
                    if cards[i] != cards[j] and signature[cards[i]] == signature[cards[j]]:
                        ambiguous.append((i, j))

            # Count how many ambiguous pairs become unique
            temp_signature = {}
            for card in cards:
                sig = set()
                for h in temp_hints:
                    if card in h:
                        sig.add(h)
                temp_signature[card] = frozenset(sig)

            unique_pairs = 0
            for i, j in ambiguous:
                if temp_signature[cards[i]] != temp_signature[cards[j]]:
                    unique_pairs += 1

            reduction = len(ambiguous) - unique_pairs

            if reduction > max_reduction:
                max_reduction = reduction
                best_hint = f"value::{value}"

        if best_hint is None:
            # No hint can reduce ambiguity (already unique or no ambiguity left)
            break

        hints.add(best_hint)

    print(len(hints))

