import sys
sys.setrecursionlimit(1 << 25)

def find(parent, x):
    if parent[x] != x:
        parent[x] = find(parent, parent[x])
    return parent[x]

def union(parent, rank, x, y):
    px = find(parent, x)
    py = find(parent, y)
    if px == py:
        return False
    if rank[px] < rank[py]:
        parent[px] = py
    else:
        parent[py] = px
        if rank[px] == rank[py]:
            rank[px] += 1
    return True

def kruskal(n, edges):
    edges.sort()
    parent = list(range(n + 1))
    rank = [1] * (n + 1)
    mst_edges = []

    for e, a, b in edges:
        if union(parent, rank, a, b):
            mst_edges.append((a, b, e))

    return mst_edges

def build_tree(n, mst_edges):
    tree = [[] for _ in range(n + 1)]
    edge_weights = {}

    for a, b, e in mst_edges:
        tree[a].append(b)
        tree[b].append(a)
        edge_weights[(a, b)] = e
        edge_weights[(b, a)] = e

    return tree, edge_weights

# Using BFS to find the maximum edge weight on the path from start to end
# We'll use a dictionary to store the maximum edge weight from the start to each node

def bfs_max_edge(tree, edge_weights, start, end):
    from collections import deque
    q = deque([(start, -1, 0)])  # (current node, parent, max_edge_weight_on_path)
    visited = {start}

    while q:
        node, parent, max_weight = q.popleft()

        if node == end:
            return max_weight

        for neighbor in tree[node]:
            if neighbor != parent:
                # The edge weight between node and neighbor
                edge_weight = edge_weights[(node, neighbor)]
                new_max = max(max_weight, edge_weight)

                if neighbor not in visited:
                    visited.add(neighbor)
                    q.append((neighbor, node, new_max))

    return 0


def main():
    data = sys.stdin.read().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    edges = []
    for _ in range(m):
        a = int(next(it))
        b = int(next(it))
        e = int(next(it))
        edges.append((e, a, b))

    mst_edges = kruskal(n, edges)
    tree, edge_weights = build_tree(n, mst_edges)

    for e, a, b in edges:
        # Check if edge is in MST
        if (a, b, e) in mst_edges or (b, a, e) in mst_edges:
            continue

        # Find maximum edge weight on the path between a and b in MST
        max_edge = bfs_max_edge(tree, edge_weights, a, b)

        # E_max is the minimum of the edge's energy and the maximum edge weight on the path
        print(min(e, max_edge))

