def solve():
    n = int(input())

    # Create a graph where edges connect numbers and their multiples
    # Each edge has weight equal to the factor

    # We need to find the longest path in this graph

    # Use DFS to find the longest path from each node
    max_score = 0

    # For each number from 2 to n, try starting from it
    for start in range(2, n + 1):
        # Use DFS to find the longest path starting from start
        def dfs(current, visited):
            nonlocal max_score

            # Try all possible transformations
            # Go to all multiples of current
            for m in range(current * 2, n + 1, current):
                if not visited[m]:
                    visited[m] = True
                    score = dfs(m, visited)
                    if score is not None:
                        score += m // current
                    if score is not None:
                        max_score = max(max_score, score)
                    visited[m] = False

            # Go to all divisors of current (excluding current itself)
            for m in range(current // 2, current):
                if current % m == 0 and m >= 2:
                    if not visited[m]:
                        visited[m] = True
                        score = dfs(m, visited)
                        if score is not None:
                            score += current // m
                        if score is not None:
                            max_score = max(max_score, score)
                        visited[m] = False

            # No more transformations possible
            return None

        visited = [False] * (n + 1)
        dfs(start, visited)

    print(max_score)

