def is_good(table):
    """Check if the table is good"""
    n = len(table)
    if n == 1:
        return True

    for i in range(n - 1):
        row1 = table[i]
        row2 = table[i + 1]

        # Find the first position where they differ
        for j in range(len(row1)):
            if row1[j] != row2[j]:
                if row1[j] > row2[j]:
                    return False
                break
    return True

def solve():
    n, m = map(int, input().split())
    table = []

    for _ in range(n):
        table.append(input().strip())

    if is_good(table):
        print(0)
        return

    # Try removing columns one by one until we find a good table
    # Start with the original table
    current_table = [list(row) for row in table]

    for remove_col in range(m):
        # Remove column 'remove_col'
        current_table = [row[:remove_col] + row[remove_col+1:] for row in current_table]

        if is_good(current_table):
            print(remove_col + 1)
            return

    # If we've removed all columns, we have an empty table
    print(m)

