def solve():
    x, y, n, d = map(int, input().split())
    vectors = [tuple(map(int, input().split())) for _ in range(n)]

    from functools import lru_cache

    # Calculate distance squared to avoid floating point
    def dist_sq(a, b):
        return a*a + b*b

    # Check if distance from origin exceeds d
    def exceeds_d(x, y):
        return dist_sq(x, y) > d * d

    # Memoization cache
    @lru_cache(maxsize=None)
    def game(pos, anton_reflected, dasha_reflected):
        x, y = pos

        # Check if current player loses immediately
        if exceeds_d(x, y):
            return False  # Current player loses

        # Try all possible moves
        for dx, dy in vectors:
            new_x = x + dx
            new_y = y + dy
            # Check if this move leads to a losing position for the opponent
            if not game((new_x, new_y), anton_reflected, dasha_reflected):
                return True  # Current player can win by making this move

        # Try reflection (if available)
        if not anton_reflected:
            new_x, new_y = y, x  # Reflect over y=x
            if not game((new_x, new_y), True, dasha_reflected):
                return True

        if not dasha_reflected:
            new_x, new_y = y, x  # Reflect over y=x
            if not game((new_x, new_y), anton_reflected, True):
                return True

        # No winning move found
        return False

    # Anton goes first, no reflections used
    if game((x, y), False, False):
        print("Anton")
    else:
        print("Dasha")

