    from functools import lru_cache

    # Calculate distance squared to avoid floating point
    def dist_sq(a, b):
        return a*a + b*b

    # Check if distance from origin exceeds d
    def exceeds_d(x, y):
        return dist_sq(x, y) > d * d

    # Memoization cache
    @lru_cache(maxsize=None)
    def game(pos, anton_reflected, dasha_reflected):
        x, y = pos

        # Try all possible moves
        for dx, dy in vectors:
            new_x = x + dx
            new_y = y + dy

            # Check if this move leads to a losing position for the opponent
            # If the new position exceeds d, the current player loses
            if exceeds_d(new_x, new_y):
                continue  # Current player loses, so this move is not good

