import sys

def solve(a, b, s):
    # Calculate displacement after one full cycle
    dx = 0
    dy = 0
    for ch in s:
        if ch == 'U': dy += 1
        elif ch == 'D': dy -= 1
        elif ch == 'R': dx += 1
        elif ch == 'L': dx -= 1

    # For each possible starting point in the cycle
    for i in range(len(s)):
        # Calculate position after i steps
        xi = 0
        yi = 0
        for j in range(i):
            ch = s[j]
            if ch == 'U': yi += 1
            elif ch == 'D': yi -= 1
            elif ch == 'R': xi += 1
            elif ch == 'L': xi -= 1

        # Check if we can reach (a, b) from this position
        # After k full cycles, we need:
        # k * dx + xi = a
        # k * dy + yi = b

        if dx == 0 and dy == 0:
            # If dx and dy are both 0, we're just repeating the same position
            # So we need to check if (xi, yi) == (a, b)
            if xi == a and yi == b:
                return True
        else:
            # Check if (a - xi) and (b - yi) are non-negative multiples of dx and dy
            if dx != 0 and dy != 0:
                if (a - xi) % dx == 0 and (b - yi) % dy == 0:
                    k1 = (a - xi) // dx
                    k2 = (b - yi) // dy
                    if k1 == k2 and k1 >= 0:
                        return True
            elif dx != 0:
                if (a - xi) % dx == 0 and (b - yi) == 0:
                    k1 = (a - xi) // dx
                    if k1 >= 0:
                        return True
            elif dy != 0:
                if (b - yi) % dy == 0 and (a - xi) == 0:
                    k1 = (b - yi) // dy
                    if k1 >= 0:
                        return True

    return False

a, b = map(int, sys.stdin.readline().split())
s = sys.stdin.readline().strip()

if solve(a, b, s):
    print("Yes")
else:
    print("No")
"}

