# Maps opening brackets to their matching closing brackets
opening_to_closing = {"[": "]", "(": ")", "{": "}", "<": ">"}

# Stack to keep track of opening brackets
stack = []
replacements = 0

# Traverse the string
for char in s:
    if char in opening_to_closing:
        # Opening bracket, push to stack
        stack.append(char)
    else:
        # Closing bracket, try to match with the most recent opening bracket
        if not stack:
            # No matching opening bracket available
            print("Impossible")
            exit()

        popped = stack.pop()

        # Check if this closing bracket matches the popped opening bracket
        # If not, we need a replacement
        if opening_to_closing[popped] != char:
            replacements += 1

# After processing all characters, check if all opening brackets have been matched
if stack:
    print("Impossible")
else:
    print(replacements)
