import sys

def digit_sum(x):
    """Return the sum of digits of x"""
    return sum(int(d) for d in str(x))

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    a = int(data[0])
    b = int(data[1])
    c = int(data[2])

    solutions = []

    # Try all possible digit sums (max 9*9=81)
    for s in range(1, 82):
        # Calculate x from the equation x = b·s^a + c
        try:
            x = b * (s ** a) + c
        except OverflowError:
            continue

        # Check if x is in the valid range and has the correct digit sum
        if 0 < x < 10**9 and digit_sum(x) == s:
            solutions.append(x)

    # Output the results
    print(len(solutions))
    if solutions:
        print(' '.join(map(str, solutions)))

if __name__ == "__main__":
    solve()
