import sys

def solve() -> None:
    data = sys.stdin.read().strip().split()
    if not data:
        return

    n = int(data[0])
    k = int(data[1])
    a = list(map(int, data[2:2+n]))

    # Find the longest subsegment with at most k zeroes
    left = 0
    max_len = 0
    zeroes = 0

    for right in range(n):
        if a[right] == 0:
            zeroes += 1

        # If we have more zeroes than k, move left
        while zeroes > k:
            if a[left] == 0:
                zeroes -= 1
            left += 1

        # Update max length
        max_len = max(max_len, right - left + 1)

    # Now find the actual subsegment and mark it
    left = 0
    zeroes = 0

    for right in range(n):
        if a[right] == 0:
            zeroes += 1

        # If we have more zeroes than k, move left
        while zeroes > k:
            if a[left] == 0:
                zeroes -= 1
            left += 1

        # If we've found the longest segment, mark it
        if right - left + 1 == max_len:
            # Mark all positions from left to right as 1
            for i in range(left, right + 1):
                a[i] = 1
            break

    print(max_len)
    print(' '.join(map(str, a)))

