def solve() -> None:
    s1 = sys.stdin.readline().strip()
    s2 = sys.stdin.readline().strip()

    # Map each character in s1 to its positions
    char_positions = {}
    for i, c in enumerate(s1):
        if c not in char_positions:
            char_positions[c] = []
        char_positions[c].append(i)

    # Check if all characters in s2 exist in s1
    for c in s2:
        if c not in char_positions:
            print(-1)
            return

    # Find the minimum number of s1 copies needed
    # We'll track our current position in the 'virtual' concatenated s1 string
    virtual_pos = 0
    count = 1  # We always need at least one copy

    for c in s2:
        positions = char_positions[c]

        # Find the smallest position >= virtual_pos
        found = False
        for pos in positions:
            if pos >= virtual_pos:
                virtual_pos = pos + 1
                found = True
                break

        if not found:
            # We need to wrap around, use another copy
            count += 1
            virtual_pos = positions[0] + 1

    print(count)

