import sys

def solve() -> None:
    n = int(sys.stdin.readline())
    a = list(map(int, sys.stdin.readline().split()))

    # Compute prefix counts: number of times a[i] appears in positions 1..i
    prefix = [0] * (n + 1)  # 1-indexed
    freq = {}  # map value -> count
    for i in range(1, n + 1):
        val = a[i - 1]
        if val in freq:
            freq[val] += 1
        else:
            freq[val] = 1
        prefix[i] = freq[val]

    # Compute suffix counts: number of times a[j] appears in positions j..n
    suffix = [0] * (n + 1)  # 1-indexed
    freq = {}  # map value -> count (from right)
    for j in range(n, 0, -1):
        val = a[j - 1]
        if val in freq:
            freq[val] += 1
        else:
            freq[val] = 1
        suffix[j] = freq[val]

    # Fenwick Tree for counting occurrences of values in prefix
    class BIT:
        def __init__(self, size: int):
            self.size = size
            self.tree = [0] * (size + 2)
        def update(self, val: int, delta: int):
            # add delta to index val
            i = val
            while i <= self.size:
                self.tree[i] += delta
                i += i & -i
        def query(self, val: int) -> int:
            # sum of counts for indices 1..val
            ans = 0
            i = val
            while i > 0:
                ans += self.tree[i]
                i -= i & -i
            return ans
        def range_query(self, l: int, r: int) -> int:
            # sum of counts for indices l..r
            return self.query(r) - self.query(l - 1)

    bit = BIT(n + 2)  # values up to n
    ans = 0
    for j in range(1, n + 1):
        target = suffix[j]
        # count number of prefix[i] > target (i < j)
        cnt = bit.range_query(target + 1, n)
        ans += cnt
        # add prefix[j] to BIT
        bit.update(prefix[j], 1)

    print(ans)

if __name__ == '__main__':
    solve()
"}

