def solve():
    data = input().split()
    if not data:
        return
    n = int(data[0])
    cards = list(map(int, data[1:]))

    if n == 1:
        print(-1)
        return

    cards.sort()
    ans = set()

    # Case 1: x is at the beginning
    # Try inserting x before cards[0]
    for i in range(1, n):
        d = cards[i] - cards[0]
        if all(cards[j] == cards[0] + j * d for j in range(1, n)):
            ans.add(cards[0] - d)

    # Case 2: x is at the end
    # Try inserting x after cards[-1]
    for i in range(1, n):
        d = cards[-1] - cards[i-1]
        if all(cards[j] == cards[0] + j * d for j in range(1, n)):
            ans.add(cards[-1] + d)

    # Case 3: x is in the middle
    # Try inserting x between each pair of cards
    for i in range(1, n):
        for j in range(i+1, n):
            d = cards[j] - cards[i]
            # Check if all existing cards match the pattern
            if all(cards[k] == cards[0] + k * d for k in range(1, n)):
                # Check if the new card fits
                x = cards[i] - d
                ans.add(x)

    # Remove duplicates and sort
    ans = sorted(ans)

    if not ans:
        print(0)
    else:
        print(len(ans))
        print(' '.join(map(str, ans)))

solve()
