import sys

def solve()
    a, b, c = map(int, sys.stdin.read().split())

    solutions = []

    # s(x) is the sum of digits of x, and x < 10^9
    # Maximum possible sum of digits is 9 * 9 = 81 (for 999999999)
    # Minimum possible sum of digits is 1 (for any positive number)
    for s in range(1, 82):
        # Calculate x = b * s^a + c
        try:
            x = b * (s ** a) + c
        except OverflowError:
            # If s^a is too large, we can skip
            continue

        # Check if x is within valid range
        if 0 < x < 10**9:
            # Check if sum of digits of x equals s
            if sum(int(digit) for digit in str(x)) == s:
                solutions.append(x)

    # Output results
    print(len(solutions))
    if solutions:
        print(' '.join(map(str, sorted(solutions))))

if __name__ == "__main__":
    solve()
"}

