import sys

def solve():
    n = int(sys.stdin.readline())

    if n == 1:
        print(1)
        return
    elif n == 2:
        print(2)
        return
    elif n == 3:
        print(6)
        return

    # Brute force for small n
    if n <= 20:
        max_lcm = 0
        for i in range(1, n+1):
            for j in range(i, n+1):
                for k in range(j, n+1):
                    # Calculate LCM
                    lcm_ijk = i * j * k
                    if i != j or j != k:
                        # If not all same, need to calculate actual LCM
                        lcm_ij = i * j // (i * j // gcd(i, j))
                        lcm_ijk = lcm_ij * k // (lcm_ij * k // gcd(lcm_ij, k))
                    if lcm_ijk > max_lcm:
                        max_lcm = lcm_ijk
        print(max_lcm)
        return

    # For larger n
    if n % 2 == 1:  # n is odd
        result = n * (n-1) * (n-2)
    else:  # n is even
        option1 = n * (n-1) * (n-2) // 2
        option2 = n * (n-1) * (n-3)
        result = max(option1, option2)

    print(result)

# Helper function
