    for i in range(n + 1):
        # Position to insert new card

        if i == 0:
            # Insert before first element
            # The new difference would be arr[0] - new_val = d_new
            # And new_val + d_new = arr[0]
            # So d_new = arr[0] - new_val
            # After insertion, the sequence: new_val, arr[0], arr[1], ...
