import sys

def evaluate(formula, assignment):
    # Parse and evaluate the formula with given assignment
    stack = []
    i = 0
    while i < len(formula):
        if formula[i] == '?':
            stack.append(assignment[i])
        elif formula[i] in '01':
            stack.append(int(formula[i]))
        elif formula[i] in '|&^':
            op = formula[i]
            right = stack.pop()
            left = stack.pop()
            if op == '|':
                stack.append(left | right)
            elif op == '&':
                stack.append(left & right)
            elif op == '^':
                stack.append(left ^ right)
        elif formula[i] == '(':
            stack.append('(')
        elif formula[i] == ')':
            # Evaluate inner expression
            inner = []
            depth = 0
            j = i + 1
            while j < len(formula):
                if formula[j] == '(':
                    depth += 1
                elif formula[j] == ')':
                    depth -= 1
                if depth == 0 and formula[j] == ')':
                    break
                inner.append(formula[j])
                j += 1
            inner_formula = ''.join(inner)
            inner_value = evaluate(inner_formula, assignment)
            stack.append(inner_value)
            i = j
        i += 1
    return stack[0]

