    # Check if there's at least one variable that is independent
    num_vars = formula.count('?')

    # If there's only one variable, it's independent
    if num_vars == 1:
        return True

    # Try to set each variable independently
    # Create an assignment where all '?' are set to 0
    assignment0 = [0] * num_vars
    # Create an assignment where all '?' are set to 1
    assignment1 = [1] * num_vars

    # Check if we can get different results by changing one variable at a time
    for i in range(len(formula)):
