import sys

def solve_case(grid, n):
    # Find vertices by looking at contamination levels
    vertices = []

    # Start from the lexicographically smallest vertex
    # This is the first vertex in the clockwise order
    start_x = 2
    start_y = 2

    # Trace around the polygon
    x, y = start_x, start_y

    # Try to move right
    for step in range(n):
        if grid[y][x + step] == '0':
            break
        if step >= n:
            break

    # After moving right, we should be at a vertex
    vertices.append((x + 1, y + 1))  # Convert to 1-indexed
    x += step

    # Now move down
    for step in range(n):
        if grid[y + step][x] == '0':
            break
        if step >= n:
            break

    # After moving down, we should be at a vertex
    vertices.append((x + 1, y + 1))  # Convert to 1-indexed
    y += step

    # Now move left
    for step in range(n):
        if grid[y][x - step] == '0':
            break
        if step >= n:
            break

    # After moving left, we should be at a vertex
    vertices.append((x + 1, y + 1))  # Convert to 1-indexed
    x -= step

    # Now move up
    for step in range(n):
        if grid[y - step][x] == '0':
            break
        if step >= n:
            break

    # After moving up, we should be at a vertex
    vertices.append((x + 1, y + 1))  # Convert to 1-indexed
    y -= step

    # Check if we found all vertices
    if len(vertices) < 4:
        return None

    # Return the vertices
    return vertices

