    n = int(input())
    a = list(map(int, input().split()))

    # Sort the array
    a.sort()

    # Build graph
    graph = {}
    for i in range(n):
        closest = None
        min_xor = float('inf')

        # Check adjacent elements (i-1 and i+1)
        for j in range(i-1, i+2):
            if 0 <= j < n:
                xor_val = a[i] ^ a[j]
                if xor_val < min_xor:
                    min_xor = xor_val
                    closest = j

