def main():
    n, m = map(int, sys.stdin.readline().split())
    edges = [[] for _ in range(n + 1)]  # 1-indexed
    for _ in range(m):
        u, v = map(int, sys.stdin.readline().split())
        edges[u].append(v)
        edges[v].append(u)

    # Find vertices with degree 0
    zero_degrees = [i for i in range(1, n + 1) if len(edges[i]) == 0]

    # Build subgraph for BFS (only vertices with degree >= 1)
    adj = [[] for _ in range(n + 1)]
    for i in range(1, n + 1):
        if len(edges[i]) > 0:
            for j in edges[i]:
                adj[i].append(j)

    # Check bipartition
    color = [-1] * (n + 1)
    is_bipartite = True

    def bfs(start):
        nonlocal is_bipartite
        q = [start]
        color[start] = 0
        while q:
            u = q.pop(0)
            for v in adj[u]:
                if color[v] == -1:
                    color[v] = color[u] ^ 1
                    q.append(v)
                elif color[v] == color[u]:
                    is_bipartite = False
                    return

    # Find a connected component to start BFS
    for i in range(1, n + 1):
        if len(edges[i]) > 0 and color[i] == -1:
            bfs(i)
            if not is_bipartite:
                break

    if not is_bipartite:
        print(-1)
    else:
        # Separate into two parts
        part0 = []
        part1 = []
        for i in range(1, n + 1):
            if len(edges[i]) > 0:
                if color[i] == 0:
                    part0.append(i)
                else:
                    part1.append(i)

        # Check if both parts are non-empty
