# This ensures no 'V' is immediately followed by a 'K'
target = []
for char in 'K':
    target.extend([char] * counts.get(char, 0))
for char in 'ABCDEFGHIJKLMNOPQRSTUVWXYZ':
    if char != 'V':
        target.extend([char] * counts.get(char, 0))
for char in 'V':
    target.extend([char] * counts.get(char, 0))

# Now count the minimum number of adjacent swaps needed
def count_swaps(original, target):
    # This is the same as the number of inversions needed to transform original to target
    # We can do this by tracking the positions of each character

    # Create a list of indices for each character in the original string
    original_pos = {}
    for i, char in enumerate(original):
        original_pos[char] = original_pos.get(char, []) + [i]

    # Create a list of indices for each character in the target string
    target_pos = {}
    for i, char in enumerate(target):
        target_pos[char] = target_pos.get(char, []) + [i]

    # For each character, calculate the number of swaps needed to move elements to target positions
    swaps = 0

    # Process characters in the order they appear in the target
    for char in target:
        if char not in original_pos:
            continue

        # Get the source positions and target positions for this character
        src = original_pos[char]
        tgt = target_pos[char]

        # Calculate swaps needed to move these elements to their target positions
        # We can use a greedy approach
        for s_idx, t_idx in zip(src, tgt):
            # Count how many elements need to move past this one
            move_count = 0
            for s_idx2, t_idx2 in zip(src, tgt):
                if s_idx2 > s_idx and t_idx2 < t_idx:
                    move_count += 1
            swaps += move_count

    return swaps

original = list(s)
