import sys
from collections import deque

def bfs(graph, match_u, match_v, dist_u, dist_v):
    dist_u[:] = [-1] * len(dist_u)
    dist_v[:] = [-1] * len(dist_v)
    queue = deque()

    for u in range(len(dist_u)):
        if match_u[u] == -1:
            dist_u[u] = 0
            queue.append(u)

    while queue:
        u = queue.popleft()
        for v in graph[u]:
            if dist_v[match_v[v]] == -1:
                dist_v[match_v[v]] = dist_u[u] + 1
                queue.append(match_v[v])

    return dist_u[-1] != -1

def dfs(u, match_u, match_v, dist_u, dist_v):
    for v in graph[u]:
        if dist_v[match_v[v]] == dist_u[u] + 1:
            if dfs(match_v[v], match_u, match_v, dist_u, dist_v):
                match_u[u] = v
                match_v[v] = u
                return True
    dist_u[u] = -1
    return False

