# For each starting point from 2 to n,
# find the maximum score we can achieve
max_score = 0

for start in range(2, n + 1):
    current = start
    score = 0

    # Multiply by largest possible factor until we can't
    while True:
        largest_factor = 1
        for f in range(2, n // current + 1):
            if current * f <= n:
                largest_factor = f

        if largest_factor == 1:
            break

        score += largest_factor
        current *= largest_factor

    # Now divide by largest possible factor to go back down
    while True:
        if current == start:
            break

        largest_factor = 1
        for f in range(2, current // start + 1):
            if current % f == 0:
                largest_factor = f

        if largest_factor == 1:
            break

        score += largest_factor
        current //= largest_factor

    max_score = max(max_score, score)

print(max_score)
