n, m, w = map(int, input().split())
weights = list(map(int, input().split()))
beauties = list(map(int, input().split()))

# Find friendship groups using DSU
class DSU:
    def __init__(self, n):
        self.parent = list(range(n))
        self.rank = [0] * n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        x_root = self.find(x)
        y_root = self.find(y)
        if x_root == y_root:
            return
        if self.rank[x_root] < self.rank[y_root]:
            self.parent[x_root] = y_root
        else:
            self.parent[y_root] = x_root
            if self.rank[x_root] == self.rank[y_root]:
                self.rank[x_root] += 1

dsu = DSU(n)
for _ in range(m):
    x, y = map(int, input().split())
    dsu.union(x-1, y-1)

# Group by root
from collections import defaultdict
groups = defaultdict(list)
for i in range(n):
    root = dsu.find(i)
    groups[root].append(i)

# Now solve the knapsack problem with group constraints
# dp[i] = max beauty for weight i
# We'll iterate through groups and update dp accordingly
dp = [0] * (w + 1)

for group in groups.values():
    # Option 1: Take all Hoses from this group
    total_weight = sum(weights[i] for i in group)
    total_beauty = sum(beauties[i] for i in group)

    # Option 2: Take no more than one from this group (0-1 knapsack for the group)
    # We'll work on a temporary dp array
    temp_dp = dp[:]

    # Consider taking all
    if total_weight <= w:
        for i in range(w, total_weight - 1, -1):
            dp[i] = max(dp[i], temp_dp[i - total_weight] + total_beauty)

    # Consider taking one from the group
    for i in range(w, -1, -1):
        for j, (weight, beauty) in enumerate(zip(weights, beauties)):
            if j in group and i >= weight:
                dp[i] = max(dp[i], temp_dp[i - weight] + beauty)

print(dp[w])
